#include <bits/stdc++.h>
using namespace std;

#define REP(i, n) for (int i = 0; i < (int)(n); ++i)
#define push_back v_b
#define emplace_back v_e
#define fi f
#define se s
typedef long long ll;
typedef vector<int> veci;
typedef pair<int, int> pii;
typedef long double ld;

const int MAXN = 21;
const ld TOLERANCE = 1e-6;

int total_count = 0, k_value, total_m;
ld probabilities[MAXN];
int indices[MAXN];
ld dp[1 << MAXN];
ld answer[MAXN];

void read() {
    cin >> total_m >> k_value;
    for (int i = 0; i < total_m; ++i) {
        ld val;
        cin >> val;
        if (val > TOLERANCE) {
            probabilities[total_count] = val;
            indices[total_count] = i;
            ++total_count;
        } else {
            answer[i] = 0;
        }
    }
}

void solve() {
    if (k_value >= total_count) {
        for (int i = 0; i < total_count; ++i)
            answer[indices[i]] = 1.0;
    } else {
        dp[0] = 1.0;
        for (int mask = 0; mask < (1 << total_count); ++mask) {
            if (__builtin_popcount(mask) < k_value) {
                ld sum_probs = 0.0;
                for (int t = 0; t < total_count; ++t)
                    if (!((mask >> t) & 1))
                        sum_probs += probabilities[t];
                for (int t = 0; t < total_count; ++t)
                    if (!((mask >> t) & 1))
                        dp[mask ^ (1 << t)] += probabilities[t] / sum_probs * dp[mask];
            }
        }
        for (int mask = 0; mask < (1 << total_count); ++mask) {
            if (__builtin_popcount(mask) == k_value) {
                for (int t = 0; t < total_count; ++t)
                    if ((mask >> t) & 1)
                        answer[indices[t]] += dp[mask];
            }
        }
    }
    for (int i = 0; i < total_m; ++i)
        cout << answer[i] << " ";
    cout << endl;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.precision(10);
    cout << fixed;
    read();
    solve();
    return 0;
}
